WORD = dict(b=1, w=2, l=4)

def rows(d, address, length, element):
    """the table's values as rows of hex (16 bytes a row), the way code_tables.json keeps them"""
    w = WORD[element]
    vals = ['%0*X' % (2 * w, int.from_bytes(d[a:a + w], 'big')) for a in range(address, address + length, w)]
    per = 16 // w
    return [' '.join(vals[i:i + per]) for i in range(0, len(vals), per)]

def encode(rs, element):
    """the bytes back from those rows"""
    w = WORD[element]
    return b''.join(int(v, 16).to_bytes(w, 'big') for r in rs for v in r.split())

def extract(d):
    return [dict(name=n, address='%06X' % a, length=ln, element=e, used_by=u, note=note, rows=rows(d, a, ln, e))
            for a, ln, e, n, u, note in TABLES]
